import { useState, useRef } from "react";
import { useParams, useNavigate } from "react-router-dom";
import {
  ArrowLeft, Download, MapPin, User, Clock, FileText,
  Camera, ScanText, Target, AlertTriangle, CheckCircle2,
  Sparkles, Image as ImageIcon, Shield, ChevronRight,
} from "lucide-react";
import { Card, PageHeader, Button, ScoreRing, GradeBadge, RiskLevelBadge, RiskStatusBadge } from "@/components/ui";
import { useInspection, usePhotosByInspection, useRisksByInspection, usePhoto, useStoreName } from "@/lib/data";
import { cn } from "@/lib/utils";
import type { Risk } from "@/types";

export default function InspectionDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const insp = useInspection(id || "");
  const storeName = useStoreName(insp?.storeId || "");
  const photos = usePhotosByInspection(insp?.id || "");
  const risks = useRisksByInspection(insp?.id || "");
  // 只保存 activeRiskId，activeRisk 和 activePhotoId 从当前数据派生，避免失步
  const [activeRiskId, setActiveRiskId] = useState<string>("");
  const photoRefs = useRef<Record<string, HTMLDivElement | null>>({});

  // activeRisk 从 risks 派生：优先用选中的 ID，否则取第一个
  const activeRisk = risks.find((r) => r.id === activeRiskId) || risks[0] || null;
  const activePhotoId = activeRisk?.photoId || photos[0]?.id || "";
  const activePhoto = usePhoto(activePhotoId);

  // 记录不存在
  if (!insp) {
    return (
      <div className="animate-fade-in flex flex-col items-center justify-center min-h-[50vh] text-center">
        <div className="w-16 h-16 rounded-2xl bg-ink-100 flex items-center justify-center mb-4">
          <Shield className="w-8 h-8 text-ink-400" />
        </div>
        <h2 className="text-xl font-bold text-ink-800 mb-2">巡检记录不存在</h2>
        <p className="text-sm text-ink-500 mb-6">该巡检 ID 可能已被删除或地址输入有误</p>
        <Button variant="gradient" onClick={() => navigate("/inspection")}>
          <ArrowLeft className="w-4 h-4" /> 返回巡检列表
        </Button>
      </div>
    );
  }

  const handleRiskClick = (risk: Risk) => {
    setActiveRiskId(risk.id);
    setTimeout(() => {
      const ref = photoRefs.current[risk.photoId];
      if (ref) ref.scrollIntoView({ behavior: "smooth", block: "center" });
    }, 50);
  };

  const handlePDF = () => {
    navigate(`/report/${insp.id}`);
  };

  return (
    <div className="animate-fade-in">
      <PageHeader
        title="巡检详情"
        subtitle={insp.id}
        actions={
          <div className="flex gap-2">
            <Button variant="secondary" onClick={() => navigate("/inspection")}>
              <ArrowLeft className="w-4 h-4" /> 返回
            </Button>
            <Button variant="gradient" onClick={handlePDF}>
              <Download className="w-4 h-4" /> 下载 PDF 报告
            </Button>
          </div>
        }
      />

      {/* 基本信息 + 得分 */}
      <div className="grid grid-cols-3 gap-5 mb-5">
        <Card className="col-span-2 p-6 relative overflow-hidden">
          <div className="absolute top-0 right-0 w-40 h-40 bg-gradient-to-br from-brand-50/50 to-transparent rounded-full blur-2xl pointer-events-none" />
          <div className="relative">
            <div className="flex items-center gap-2 text-[10px] text-ink-400 font-semibold tracking-widest uppercase mb-4">
              <FileText className="w-3 h-3" /> 巡检信息
            </div>
            <div className="grid grid-cols-2 gap-x-8 gap-y-5">
              <InfoItem icon={<MapPin className="w-4 h-4" />} label="巡检门店" value={storeName} />
              <InfoItem icon={<FileText className="w-4 h-4" />} label="巡检模板" value={insp.templateName} badge />
              <InfoItem icon={<User className="w-4 h-4" />} label="巡检员" value={insp.inspector} avatar />
              <InfoItem icon={<Clock className="w-4 h-4" />} label="巡检时间" value={insp.inspectTime} mono />
            </div>
          </div>
        </Card>

        <Card className="p-6 relative overflow-hidden" glow>
          <div className="absolute -top-10 -right-10 w-40 h-40 bg-gradient-to-br from-cyan-100/40 to-transparent rounded-full blur-2xl pointer-events-none" />
          <div className="relative flex items-center gap-5">
            <ScoreRing score={insp.score} size={110} />
            <div className="flex-1">
              <div className="text-[10px] text-ink-400 font-semibold tracking-widest uppercase mb-1">巡检评级</div>
              <div className="mb-3"><GradeBadge grade={insp.grade} large /></div>
              <div className="space-y-1.5">
                <RiskBar label="高" count={insp.highRiskCount} color="bg-red-500" total={insp.riskCount || 1} />
                <RiskBar label="中" count={insp.midRiskCount} color="bg-orange-500" total={insp.riskCount || 1} />
                <RiskBar label="低" count={insp.lowRiskCount} color="bg-amber-500" total={insp.riskCount || 1} />
              </div>
            </div>
          </div>
        </Card>
      </div>

      {/* 仅汇总记录提示 */}
      {insp.summaryOnly && (
        <div className="mb-5 flex items-center gap-3 p-4 rounded-xl bg-amber-50 border border-amber-200 text-amber-800">
          <AlertTriangle className="w-4 h-4 flex-shrink-0" />
          <div className="text-sm">
            <strong className="font-semibold">仅汇总记录</strong>
            <span className="text-amber-700 ml-1">— 本次巡检仅有统计数字，无风险明细和取证照片。</span>
          </div>
        </div>
      )}

      {/* 风险溯源 + 照片 */}
      <div className="grid grid-cols-3 gap-5 mb-5">
        {/* 风险清单 */}
        <Card className="p-5">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-semibold text-ink-800 flex items-center gap-2">
              <div className="w-6 h-6 rounded-md bg-gradient-to-br from-red-500 to-orange-500 flex items-center justify-center">
                <AlertTriangle className="w-3.5 h-3.5 text-white" />
              </div>
              不符合项清单
            </h3>
            <span className="text-xs text-ink-400 font-mono">{risks.length} 项</span>
          </div>
          <div className="space-y-2 max-h-[420px] overflow-y-auto thin-scroll pr-1">
            {risks.map((risk) => (
              <div
                key={risk.id}
                onClick={() => handleRiskClick(risk)}
                className={cn(
                  "group relative p-3.5 rounded-xl border cursor-pointer transition-all duration-200",
                  activeRisk?.id === risk.id
                    ? "border-brand-300 bg-gradient-to-br from-brand-50/80 to-cyan-50/40 shadow-soft"
                    : "border-ink-200/60 hover:border-brand-200 hover:bg-ink-50/40"
                )}
              >
                {activeRisk?.id === risk.id && (
                  <span className="absolute left-0 top-3 bottom-3 w-0.5 rounded-r bg-gradient-to-b from-brand-500 to-cyan-500" />
                )}
                <div className="flex items-center justify-between mb-1.5">
                  <RiskLevelBadge level={risk.level} size="sm" />
                  <RiskStatusBadge status={risk.status} />
                </div>
                <p className="text-sm text-ink-800 line-clamp-2 leading-relaxed">{risk.description}</p>
                <div className="flex items-center gap-3 mt-2 text-[11px] text-ink-400">
                  <span className="flex items-center gap-1">
                    <Target className="w-3 h-3" />
                    <span className="font-mono tabular-nums">{(risk.confidence * 100).toFixed(0)}%</span>
                  </span>
                  <span>·</span>
                  <span>{risk.category}</span>
                </div>
              </div>
            ))}
            {risks.length === 0 && !insp.summaryOnly && (
              <div className="flex flex-col items-center py-10 text-ink-300">
                <div className="w-12 h-12 rounded-full bg-emerald-50 flex items-center justify-center mb-3">
                  <CheckCircle2 className="w-6 h-6 text-emerald-400" />
                </div>
                <p className="text-sm text-ink-500">本次巡检无风险项</p>
                <p className="text-xs text-ink-400 mt-1">所有检查项均符合标准</p>
              </div>
            )}
            {risks.length === 0 && insp.summaryOnly && (
              <div className="flex flex-col items-center py-10 text-ink-300">
                <div className="w-12 h-12 rounded-full bg-amber-50 flex items-center justify-center mb-3">
                  <FileText className="w-6 h-6 text-amber-400" />
                </div>
                <p className="text-sm text-ink-500">历史汇总记录</p>
                <p className="text-xs text-ink-400 mt-1">明细未归档，仅保留统计数字</p>
              </div>
            )}
          </div>
        </Card>

        {/* 照片 + AI 识别 */}
        <Card className="col-span-2 p-5">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-semibold text-ink-800 flex items-center gap-2">
              <div className="w-6 h-6 rounded-md bg-gradient-to-br from-brand-700 to-cyan-600 flex items-center justify-center">
                <Camera className="w-3.5 h-3.5 text-white" />
              </div>
              巡检取证照片
              <span className="text-xs text-ink-400 font-mono">{photos.length} 张</span>
            </h3>
            <span className="text-[10px] text-ink-400 uppercase tracking-wider">AI Analysis</span>
          </div>
          {activePhoto && (
            <div className="mb-4" ref={(el) => { photoRefs.current[activePhoto.id] = el; }}>
              <div className="relative rounded-xl overflow-hidden bg-ink-100 group" style={{ height: 300 }}>
                <img
                  src={activePhoto.url}
                  alt={activePhoto.category}
                  className="w-full h-full object-cover"
                />
                {/* 红框标注 */}
                {activePhoto.box && (
                  <div className="absolute inset-0 pointer-events-none">
                    <div
                      className="absolute border-[3px] border-red-500 rounded transition-all duration-500"
                      style={{
                        left: `${activePhoto.box.x}%`,
                        top: `${activePhoto.box.y}%`,
                        width: `${activePhoto.box.w}%`,
                        height: `${activePhoto.box.h}%`,
                        boxShadow: "0 0 0 9999px rgba(15, 23, 42, 0.25), inset 0 0 0 1px rgba(255, 255, 255, 0.3)",
                      }}
                    >
                      <span className="absolute -top-7 left-0 inline-flex items-center gap-1 bg-red-500 text-white text-[11px] font-semibold px-2 py-0.5 rounded shadow-glow-red">
                        <Target className="w-3 h-3" /> 问题位置
                      </span>
                    </div>
                  </div>
                )}
                {/* 分类标签 */}
                <div className="absolute top-3 right-3 inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-black/60 backdrop-blur-sm text-white text-xs font-medium">
                  <ImageIcon className="w-3 h-3" />
                  {activePhoto.category}
                </div>
                {/* 左下角置信度 */}
                <div className="absolute bottom-3 left-3 inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-black/60 backdrop-blur-sm text-white text-xs">
                  <Sparkles className="w-3 h-3 text-cyan-300" />
                  AI 置信度 <span className="font-bold tabular-nums text-cyan-300">{(activePhoto.confidence * 100).toFixed(0)}%</span>
                </div>
              </div>
              {/* AI 识别详情 */}
              <div className="mt-3 relative rounded-xl bg-gradient-to-br from-brand-50/60 to-cyan-50/40 border border-brand-100/60 p-4 overflow-hidden">
                <div className="absolute -top-10 -right-10 w-32 h-32 bg-cyan-200/20 rounded-full blur-2xl pointer-events-none" />
                <div className="relative">
                  <div className="flex items-center gap-2 mb-2">
                    <div className="w-5 h-5 rounded-md bg-gradient-to-br from-cyan-500 to-brand-700 flex items-center justify-center">
                      <ScanText className="w-3 h-3 text-white" />
                    </div>
                    <span className="text-sm font-semibold text-ink-800">AI 识别结果</span>
                    <span className={cn(
                      "ml-auto text-xs px-2 py-0.5 rounded-full font-semibold",
                      activePhoto.confidence >= 0.9
                        ? "bg-emerald-100 text-emerald-700 border border-emerald-200"
                        : "bg-amber-100 text-amber-700 border border-amber-200"
                    )}>
                      置信度 {(activePhoto.confidence * 100).toFixed(0)}%
                    </span>
                  </div>
                  <p className="text-sm text-ink-700 leading-relaxed">{activePhoto.aiResult}</p>
                  {activeRisk && (
                    <div className="mt-3 pt-3 border-t border-ink-200/60 space-y-2">
                      <div className="flex items-center gap-2">
                        <Shield className="w-3.5 h-3.5 text-red-500" />
                        <span className="text-xs font-semibold text-red-600">关联风险</span>
                        <RiskLevelBadge level={activeRisk.level} size="sm" />
                        <RiskStatusBadge status={activeRisk.status} />
                      </div>
                      <p className="text-sm text-ink-800 font-medium">{activeRisk.description}</p>
                      <div className="grid grid-cols-2 gap-2 text-[11px]">
                        <div className="bg-white/60 rounded-md p-2">
                          <p className="text-ink-400 mb-0.5">判定依据</p>
                          <p className="text-ink-700">{activeRisk.basis}</p>
                        </div>
                        <div className="bg-white/60 rounded-md p-2">
                          <p className="text-ink-400 mb-0.5">整改建议</p>
                          <p className="text-ink-700">{activeRisk.suggestion}</p>
                        </div>
                      </div>
                      <button
                        onClick={() => navigate("/risk")}
                        className="w-full mt-1 flex items-center justify-between px-2.5 py-1.5 rounded-md bg-brand-50/60 hover:bg-brand-50 text-brand-700 text-xs font-medium transition group"
                      >
                        <span className="flex items-center gap-1.5">
                          <CheckCircle2 className="w-3.5 h-3.5" />
                          前往风险中心处理整改
                        </span>
                        <ChevronRight className="w-3.5 h-3.5 transition-transform group-hover:translate-x-0.5" />
                      </button>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}

          {/* 缩略图 */}
          <div className="flex gap-2 flex-wrap">
            {photos.map((ph) => (
              <button
                key={ph.id}
                onClick={() => {
                  const risk = risks.find((r) => r.photoId === ph.id);
                  if (risk) setActiveRiskId(risk.id);
                }}
                className={cn(
                  "relative w-20 h-20 rounded-lg overflow-hidden border-2 transition-all cursor-pointer",
                  activePhotoId === ph.id
                    ? "border-brand-500 shadow-glow-brand scale-105"
                    : "border-transparent opacity-60 hover:opacity-100 hover:border-ink-200"
                )}
              >
                <img src={ph.url} alt={ph.category} className="w-full h-full object-cover" />
                {risks.find((r) => r.photoId === ph.id) && (
                  <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full shadow-[0_0_6px_rgba(239,68,68,0.8)]" />
                )}
              </button>
            ))}
          </div>
        </Card>
      </div>

      {/* 整改状态汇总 */}
      <Card className="p-6">
        <div className="flex items-center justify-between mb-4">
          <h3 className="text-sm font-semibold text-ink-800 flex items-center gap-2">
            <Activity className="w-4 h-4 text-brand-700" /> 整改状态汇总
          </h3>
          <span className="text-[10px] text-ink-400 uppercase tracking-wider">Risk Pipeline</span>
        </div>
        <div className="grid grid-cols-6 gap-3">
          {[
            { label: "AI识别", count: risks.filter((r) => r.status === "ai_detected").length, color: "from-slate-400 to-slate-500", text: "text-slate-700" },
            { label: "待确认", count: risks.filter((r) => r.status === "pending").length, color: "from-amber-400 to-amber-500", text: "text-amber-700" },
            { label: "待整改", count: risks.filter((r) => r.status === "confirmed").length, color: "from-orange-400 to-orange-500", text: "text-orange-700" },
            { label: "整改中", count: risks.filter((r) => r.status === "fixing").length, color: "from-blue-400 to-blue-500", text: "text-blue-700" },
            { label: "已整改", count: risks.filter((r) => r.status === "fixed").length, color: "from-cyan-400 to-cyan-500", text: "text-cyan-700" },
            { label: "已验证", count: risks.filter((r) => r.status === "verified").length, color: "from-emerald-400 to-emerald-500", text: "text-emerald-700" },
          ].map((item) => (
            <div key={item.label} className="relative overflow-hidden rounded-xl bg-gradient-to-br from-white to-ink-50/50 border border-ink-200/60 p-4 group hover:-translate-y-0.5 transition">
              <div className={cn("absolute top-0 left-0 right-0 h-0.5 bg-gradient-to-r", item.color)} />
              <p className={cn("text-3xl font-bold font-display tabular-nums", item.text)}>{item.count}</p>
              <p className="text-xs text-ink-500 mt-1">{item.label}</p>
            </div>
          ))}
        </div>
      </Card>
    </div>
  );
}

function InfoItem({ icon, label, value, mono, avatar, badge }: { icon: React.ReactNode; label: string; value: string; mono?: boolean; avatar?: boolean; badge?: boolean }) {
  return (
    <div className="flex items-start gap-3">
      <div className="w-8 h-8 rounded-lg bg-ink-100/60 flex items-center justify-center flex-shrink-0 text-ink-500">
        {icon}
      </div>
      <div className="flex-1 min-w-0">
        <p className="text-[10px] text-ink-400 font-semibold tracking-wider uppercase">{label}</p>
        <div className="mt-1 flex items-center gap-1.5">
          {avatar && (
            <div className="w-5 h-5 rounded-full bg-gradient-to-br from-cyan-500 to-brand-700 text-white text-[10px] font-semibold flex items-center justify-center">
              {value[0]}
            </div>
          )}
          {badge ? (
            <span className="px-2 py-0.5 text-[11px] rounded-md bg-ink-100/60 text-ink-700 font-medium">{value}</span>
          ) : (
            <p className={cn("text-sm text-ink-800 font-medium", mono && "font-mono tabular-nums")}>{value}</p>
          )}
        </div>
      </div>
    </div>
  );
}

function RiskBar({ label, count, color, total }: { label: string; count: number; color: string; total: number }) {
  const pct = Math.min(100, (count / total) * 100);
  return (
    <div className="flex items-center gap-2">
      <span className="text-[10px] text-ink-500 w-3">{label}</span>
      <div className="flex-1 h-1.5 bg-ink-100/60 rounded-full overflow-hidden">
        <div className={cn("h-full rounded-full transition-all duration-700", color)} style={{ width: `${pct}%` }} />
      </div>
      <span className="text-[10px] text-ink-600 font-mono tabular-nums w-3 text-right">{count}</span>
    </div>
  );
}

function Activity({ className }: { className?: string }) {
  return (
    <svg className={className} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <polyline points="22 12 18 12 15 21 9 3 6 12 2 12" />
    </svg>
  );
}
